package cn.yueji.balance;

import android.view.*;
import android.widget.*;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.uiautomator.*;
import org.junit.*;
import org.junit.runner.RunWith;
import java.time.*;
import java.util.*;
import static org.junit.Assert.*;

@RunWith(AndroidJUnit4.class)
public class V4712UiTest {
    final V4711UiTest old=new V4711UiTest();final YuejiTest t=old.t;final V43UiTest h=old.h;
    @Before public void before(){old.before();}
    @After public void after()throws Exception{old.after();}
    Ledger.Entry income(Ledger.Data d,long amount){Ledger.Entry e=new Ledger.Entry(d.nextId(),true,amount,LocalDateTime.of(2026,10,10,12,0),"工资","",1);e.category="其他";e.cashLinked=true;d.entries.add(e);return e;}
    void shot(String name){old.old.shot("v4712-"+name+".png");}
    @Test public void sameTimeIncomeRowsHaveSeparateSignedAmountsAndColours(){Ledger.Data d=old.sample();Ledger.Entry a=income(d,50000),b=income(d,20000);t.start(d);old.history(1);t.ui(()->{TextView first=(TextView)t.findText(t.app.body,"+¥ 500.00"),second=(TextView)t.findText(t.app.body,"+¥ 200.00");assertNotNull(first);assertNotNull(second);assertEquals(Ui.RED,first.getCurrentTextColor());assertNotNull(h.desc(t.app.body,"账户金额流水entry:"+a.id));assertNotNull(h.desc(t.app.body,"账户金额流水entry:"+b.id));assertEquals(1,t.app.data.snapshots.size());});shot("same-time-income");}
    @Test public void swipeHideAndResaveIncomeRestoresOnlyDisplayNotMoney(){Ledger.Data d=old.sample();Ledger.Entry e=income(d,50000);t.start(d);old.history(1);long before=t.store.load().total();t.ui(()->h.first(t.app.body,SwipeRow.class).openUp());old.old.tap("删除");old.old.tap("删除");Ledger.Data hidden=t.store.load();assertEquals(0,AccountCash.rows(hidden,hidden.accounts.get(0)).size());assertEquals(before,hidden.total());t.ui(()->t.app.openEntry(Ledger.INCOME,t.app.data.entries.get(0)));old.save();Ledger.Data restored=t.store.load();assertEquals(1,AccountCash.rows(restored,restored.accounts.get(0)).size());assertEquals(before,restored.total());assertEquals(1,restored.entries.size());old.history(1);shot("restored-income");}
    @Test public void sameTimeManualBalanceAndFlowStaySeparateAndRejectDuplicateBalance(){Ledger.Data d=old.sample();Ledger.Entry e=income(d,50000);MonthLedger.updateAccount(d,1,e.at,1040000);t.start(d);old.history(1);assertEquals(1040000,t.store.load().balance(t.store.load().accounts.get(0)));t.ui(()->{assertNotNull(t.findText(t.app.body,"+¥ 500.00"));assertNotNull(t.findText(t.app.body,"¥ 10,400.00"));});shot("balance-and-flow");}
    @Test public void duplicateRealUpdateShowsErrorAndPreservesData(){t.start(old.sample());t.ui(()->{Ledger.Data c=t.app.copy();MonthLedger.updateAccount(c,1,LocalDateTime.now().withSecond(0).withNano(0),990000);t.app.commit(c);t.app.updateAccountBalance(AccountRecords.account(t.app.data,1),null);});String before=t.store.exportJson();old.old.tap("保存");assertNotNull(t.device.wait(Until.findObject(By.textContains("此时刻已有实测余额")),2000));assertEquals(before,t.store.exportJson());old.old.tap("知道了");old.old.tap("取消");}
    @Test public void reimbursementShowsOutflowAndReceiptWithoutIncome(){Ledger.Data d=old.sample();Ledger.Entry e=new Ledger.Entry(d.nextId(),false,80000,LocalDateTime.of(2026,10,10,12,0),"差旅垫付","",1);e.kind=Ledger.REIMBURSE;e.cashLinked=true;Ledger.Receipt r=new Ledger.Receipt(80000,LocalDateTime.of(2026,10,20,12,0));r.accountId=1;r.cashLinked=true;e.receipts.add(r);e.status=e.reimbursementStatus();d.entries.add(e);t.start(d);old.history(1);t.ui(()->{assertEquals(Ui.BLUE,((TextView)t.findText(t.app.body,"-¥ 800.00")).getCurrentTextColor());assertEquals(Ui.BLUE,((TextView)t.findText(t.app.body,"+¥ 800.00")).getCurrentTextColor());assertEquals(0,Ledger.income(t.app.data,2026));});shot("reimbursement-flows");}
    @Test public void deletingAndResavingLargeExpenseRestoresItsNegativeRow(){Ledger.Data d=old.sample();Ledger.Entry e=new Ledger.Entry(d.nextId(),false,20000,LocalDateTime.of(2026,10,10,12,0),"家具","",1);e.kind=Ledger.LARGE;e.cashLinked=true;d.entries.add(e);AccountCash.hide(d,1,"entry:"+e.id);t.start(d);t.ui(()->t.app.openEntry(Ledger.LARGE,t.app.data.entries.get(0)));old.save();Ledger.Data saved=t.store.load();assertEquals(1,AccountCash.rows(saved,saved.accounts.get(0)).size());assertEquals(980000,saved.balance(saved.accounts.get(0)));old.history(1);t.ui(()->assertNotNull(t.findText(t.app.body,"-¥ 200.00")));shot("large-expense-flow");}
    @Test public void linkedFundIsAnAmountRowAndOpeningSourcePageDoesNotCrash(){Ledger.Data d=old.sample();FundTransactions.save(d,0,0,"006431",200000,30,LocalDateTime.of(2026,10,10,12,0),null,"离线",false,true,1,new TradingCalendar());t.start(d);old.history(1);t.ui(()->{assertNotNull(t.findText(t.app.body,"-¥ 2,000.00"));assertEquals(800000,t.app.data.balance(t.app.data.accounts.get(0)));AccountCash.Flow f=AccountCash.flows(t.app.data).get(0);t.app.editAccountActivity(t.app.focusedAccount(),f);});assertNotNull(t.device.wait(Until.findObject(By.textContains("查看基金交易")),2000));shot("fund-source");old.old.tap("查看基金交易：基金 006431");assertEquals("fund_trades",t.app.page);}
    @Test public void trendHasOneDailyPointForDifferentAccountUpdates(){Ledger.Data d=old.sample();MonthLedger.updateAccount(d,1,LocalDateTime.of(2026,10,10,10,0),900000);MonthLedger.updateAccount(d,2,LocalDateTime.of(2026,10,10,20,0),450000);t.start(d);t.ui(()->{t.app.assetTab=1;t.app.render();AssetTrendChart chart=h.first(t.app.body,AssetTrendChart.class);assertNotNull(chart);Set<LocalDate> days=new HashSet<>();for(AssetHistory.Point p:chart.points)assertTrue(days.add(p.at.toLocalDate()));assertEquals(2,chart.points.size());assertEquals(Long.valueOf(1350000),chart.points.get(1).amount);h.desc(t.app.body,"资产变动趋势说明").performClick();});assertNotNull(t.device.wait(Until.findObject(By.textContains("合并为一个日末点")),2000));shot("daily-trend-help");}
    @Test public void signedCardsFitShortScreenLargeFontAndDarkTheme()throws Exception{try{t.device.executeShellCommand("wm size 1080x1920");t.device.executeShellCommand("wm density 420");t.device.executeShellCommand("settings put system font_scale 1.3");Ledger.Data d=old.sample();income(d,123456789);t.start(d);t.ui(()->{t.app.getPreferences(0).edit().putInt("appearance",2).commit();});old.history(1);t.device.waitForIdle();new V4710UiTest().assertNumbers(t.app.body);shot("dark-large-font-signed");}finally{t.device.executeShellCommand("wm size reset");t.device.executeShellCommand("wm density reset");t.device.executeShellCommand("settings put system font_scale 1.0");}}
}
